{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-vIsrQc/src/address.js","content":"/**
 * Cell address helpers: column letters <-> column numbers, and the strict
 * (declaration) vs. loose (formula word) address grammars.
 */

/** Convert 1-2 uppercase column letters (A..ZZ) to a 1-based column number. */
export function colToNum(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/** Convert a 1-based column number back to its uppercase letters. */
export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

const STRICT_ADDR_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parse a declaration-side address token strictly: 1-2 letters, 1-3 digits,
 * row at least 1. Returns null when the token is not a valid address.
 */
export function parseStrictAddress(token) {
  const m = STRICT_ADDR_RE.exec(token)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  return { key: letters + row, col: colToNum(letters), row }
}

const WORD_SPLIT_RE = /^([A-Za-z]+)([0-9]*)$/

/**
 * Classify a formula WORD token as an in-range or out-of-range cell address.
 * The word is assumed to already match the loose lexer pattern (letters
 * followed by optional digits).
 */
export function classifyWord(word) {
  const m = WORD_SPLIT_RE.exec(word)
  const letters = m[1]
  const digits = m[2]
  if (digits.length === 0 || digits.length > 3 || letters.length > 2) {
    return { inRange: false }
  }
  const row = parseInt(digits, 10)
  if (row < 1) return { inRange: false }
  const upperLetters = letters.toUpperCase()
  return { inRange: true, key: upperLetters + row, col: colToNum(upperLetters), row }
}

/**
 * Expand a range given by its two corner words into the list of addresses it
 * covers, ascending by column then by row. Returns null if either corner is
 * not an in-range address.
 */
export function expandRange(fromWord, toWord) {
  const a = classifyWord(fromWord)
  const b = classifyWord(toWord)
  if (!a.inRange || !b.inRange) return null
  const colMin = Math.min(a.col, b.col)
  const colMax = Math.max(a.col, b.col)
  const rowMin = Math.min(a.row, b.row)
  const rowMax = Math.max(a.row, b.row)
  const cells = []
  for (let c = colMin; c <= colMax; c++) {
    for (let r = rowMin; r <= rowMax; r++) {
      cells.push(numToCol(c) + r)
    }
  }
  return cells
}

/** Parse a canonical address key (as produced above) back into {col, row}. */
export function keyColRow(key) {
  return classifyWord(key)
}
"}

