{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-vIsrQc/src/lexer.js","content":"/**
 * Tokenizer for a formula body (the text after the leading `=`).
 */

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = new Set(['^', '*', '/', '+', '-', '=', '<', '>'])

/**
 * Tokenize a formula body. Returns null when a character is not part of the
 * grammar at all (an unrecognized character), which the parser treats the
 * same as any other grammar failure.
 */
export function tokenize(src) {
  const tokens = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch === '(') {
      tokens.push({ type: 'LP' })
      i++
      continue
    }
    if (ch === ')') {
      tokens.push({ type: 'RP' })
      i++
      continue
    }
    if (ch === ',') {
      tokens.push({ type: 'COMMA' })
      i++
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    const two = src.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'OP', value: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.has(ch)) {
      tokens.push({ type: 'OP', value: ch })
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i))
      tokens.push({ type: 'NUMBER', value: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(src.slice(i))
      tokens.push({ type: 'WORD', value: m[0] })
      i += m[0].length
      continue
    }
    return null
  }
  return tokens
}
"}

