{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-vIsrQc/src/parser.js","content":"/**
 * Recursive-descent parser for a formula body, producing an AST.
 *
 * Precedence, loosest to tightest: comparisons, then `+`/`-`, then `*`/`/`,
 * then `^`, then a leading unary `-`/`+`. The comparison and additive and
 * multiplicative operators are left-associative; `^` is right-associative;
 * a leading sign binds tighter than `^`.
 *
 * A range (`WORD ':' WORD`) parses wherever an address could appear, so that
 * a range written outside a direct function-argument position is a grammar
 * success whose misuse becomes a runtime `#ERR!` rather than a parse failure.
 */

import { tokenize } from './lexer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class SyntaxErr extends Error {}

/** Parse a formula body into an AST, or return null if the grammar rejects it. */
export function parseFormula(body) {
  const tokens = tokenize(body)
  if (tokens === null) return null
  try {
    let pos = 0
    const peek = () => tokens[pos]
    const next = () => tokens[pos++]
    const expect = (type) => {
      const t = peek()
      if (!t || t.type !== type) throw new SyntaxErr()
      return next()
    }

    function parseExpr() {
      return parseComparison()
    }

    function parseComparison() {
      let left = parseAdditive()
      while (peek() && peek().type === 'OP' && COMPARISON_OPS.has(peek().value)) {
        const op = next().value
        const right = parseAdditive()
        left = { type: 'binop', op, left, right }
      }
      return left
    }

    function parseAdditive() {
      let left = parseMultiplicative()
      while (peek() && peek().type === 'OP' && (peek().value === '+' || peek().value === '-')) {
        const op = next().value
        const right = parseMultiplicative()
        left = { type: 'binop', op, left, right }
      }
      return left
    }

    function parseMultiplicative() {
