 * Parse a sheet from raw standard input text into a Map from canonical
 * address key to a declared cell record.
 */

import { parseStrictAddress } from './address.js'

export class SheetError extends Error {}

/** Parse the sheet text, throwing SheetError with the exact required message on failure. */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const sheet = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const stripped = lines[i].replace(/^[ \t]+/, '')
    if (stripped === '' || stripped[0] === '#') continue

    const wsIdx = stripped.search(/[ \t]/)
    const addrToken = wsIdx === -1 ? stripped : stripped.slice(0, wsIdx)
    const rest = wsIdx === -1 ? '' : stripped.slice(wsIdx).replace(/^[ \t]+/, '')

    const info = parseStrictAddress(addrToken)
    if (!info) {
      throw new SheetError(`error: line ${lineNo}: invalid cell address ${addrToken}`)
    }
    if (sheet.has(info.key)) {
      throw new SheetError(`error: line ${lineNo}: cell ${info.key} is declared twice`)
    }
    sheet.set(info.key, { content: rest, col: info.col, row: info.row, ast: undefined })
  }
  return sheet
}
"}

