 * Value model and evaluation for parsed sheets.
 *
 * A value is `{ type: 'number' | 'text' | 'bool' | 'error', value }`.
 * Cell results are memoized in a tri-state cache (unstarted / computing /
 * done); a reference to a cell that is currently computing yields `#CYCLE!`,
 * which then propagates like any other error.
 */

import { classifyWord, expandRange } from './address.js'
import { parseFormula } from './parser.js'
import { formatNumber } from './format.js'

const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

const FUNCS = {
  SUM: { min: 1, max: Infinity },
  MIN: { min: 1, max: Infinity },
  MAX: { min: 1, max: Infinity },
  COUNT: { min: 1, max: Infinity },
  AVG: { min: 1, max: Infinity },
  ABS: { min: 1, max: 1 },
  IF: { min: 3, max: 3 },
}

function numberVal(value) {
  return { type: 'number', value }
}
function textVal(value) {
  return { type: 'text', value }
}
function boolVal(value) {
  return { type: 'bool', value }
}
function errorVal(value) {
  return { type: 'error', value }
}

function parseLiteral(content) {
  if (content === '') return numberVal(0)
  if (ERROR_TOKENS.includes(content)) return errorVal(content)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return numberVal(parseFloat(content))
  return textVal(content)
}

function toNumber(v) {
  if (v.type === 'number') return v
  if (v.type === 'bool') return numberVal(v.value ? 1 : 0)
  if (v.type === 'text') return errorVal('#VALUE!')
  return v
}

function finiteOrDivZero(n) {
  return Number.isFinite(n) ? numberVal(n) : errorVal('#DIV/0!')
}

function rank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2
}

function compareValues(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.type === 'number') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  const av = a.value ? 1 : 0
  const bv = b.value ? 1 : 0
  return av < bv ? -1 : av > bv ? 1 : 0
}

function getCellValue(ctx, key) {
  const state = ctx.cache.get(key)
  if (state) {
    if (state.status === 'done') return state.value
    return errorVal('#CYCLE!')
  }
  ctx.cache.set(key, { status: 'computing' })
  const value = computeCellValue(ctx, key)
  ctx.cache.set(key, { status: 'done', value })
  return value
}

function computeCellValue(ctx, key) {
  const cell = ctx.sheet.get(key)
  if (!cell) return numberVal(0)
  const content = cell.content
  if (content[0] === '=') {
    if (cell.ast === undefined) cell.ast = parseFormula(content.slice(1))
    if (cell.ast === null) return errorVal('#ERR!')
