  return textVal(content)
}

function toNumber(v) {
  if (v.type === 'number') return v
  if (v.type === 'bool') return numberVal(v.value ? 1 : 0)
  if (v.type === 'text') return errorVal('#VALUE!')
  return v
}

function finiteOrDivZero(n) {
  return Number.isFinite(n) ? numberVal(n) : errorVal('#DIV/0!')
}

function rank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2
}

function compareValues(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.type === 'number') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  const av = a.value ? 1 : 0
  const bv = b.value ? 1 : 0
  return av < bv ? -1 : av > bv ? 1 : 0
}

function getCellValue(ctx, key) {
  const state = ctx.cache.get(key)
  if (state) {
    if (state.status === 'done') return state.value
    return errorVal('#CYCLE!')
  }
  ctx.cache.set(key, { status: 'computing' })
  const value = computeCellValue(ctx, key)
  ctx.cache.set(key, { status: 'done', value })
  return value
}

function computeCellValue(ctx, key) {
  const cell = ctx.sheet.get(key)
  if (!cell) return numberVal(0)
  const content = cell.content
  if (content[0] === '=') {
    if (cell.ast === undefined) cell.ast = parseFormula(content.slice(1))
    if (cell.ast === null) return errorVal('#ERR!')
    return evalScalar(ctx, cell.ast)
  }
  return parseLiteral(content)
}

function evalArgumentValues(ctx, node) {
  if (node.type === 'range') {
    const cells = expandRange(node.from, node.to)
    if (cells === null) return [errorVal('#REF!')]
    return cells.map((key) => getCellValue(ctx, key))
  }
  return [evalScalar(ctx, node)]
}

function evalScalar(ctx, node) {
  switch (node.type) {
    case 'number':
      return numberVal(node.value)
    case 'bool':
      return boolVal(node.value)
    case 'range':
      return errorVal('#ERR!')
    case 'address': {
      const info = classifyWord(node.word)
      if (!info.inRange) return errorVal('#REF!')
      return getCellValue(ctx, info.key)
    }
    case 'unary': {
      const v = evalScalar(ctx, node.operand)
      if (v.type === 'error') return v
      const n = toNumber(v)
      if (n.type === 'error') return n
      return numberVal(node.op === '-' ? -n.value : n.value)
    }
    case 'binop':
      return evalBinop(ctx, node)
    case 'call':
      return evalCall(ctx, node)
    default:
      throw new Error(`unreachable node type ${node.type}`)
  }
}

function evalBinop(ctx, node) {
  const { op } = node
  if (COMPARISON_OPS.has(op)) {
    const l = evalScalar(ctx, node.left)
    if (l.type === 'error') return l
    const r = evalScalar(ctx, node.right)
    if (r.type === 'error') return r
    const cmp = compareValues(l, r)
    switch (op) {
      case '=':
        return boolVal(cmp === 0)
      case '<>':
        return boolVal(cmp !== 0)
      case '<':
        return boolVal(cmp < 0)
      case '<=':
        return boolVal(cmp <= 0)
      case '>':
        return boolVal(cmp > 0)
      case '>=':
        return boolVal(cmp >= 0)
    }
  }
  const l = evalScalar(ctx, node.left)
  if (l.type === 'error') return l
  const ln = toNumber(l)
  if (ln.type === 'error') return ln
  const r = evalScalar(ctx, node.right)
  if (r.type === 'error') return r
  const rn = toNumber(r)
  if (rn.type === 'error') return rn
  switch (op) {
    case '+':
      return finiteOrDivZero(ln.value + rn.value)
    case '-':
      return finiteOrDivZero(ln.value - rn.value)
    case '*':
      return finiteOrDivZero(ln.value * rn.value)
    case '/':
      if (rn.value === 0) return errorVal('#DIV/0!')
      return finiteOrDivZero(ln.value / rn.value)
    case '^':
      return finiteOrDivZero(Math.pow(ln.value, rn.value))
    default:
      throw new Error(`unreachable operator ${op}`)
  }
}

function evalCall(ctx, node) {
  const spec = FUNCS[node.name]
  if (!spec) return errorVal('#NAME?')
  const argc = node.args.length
  if (argc < spec.min || argc > spec.max) return errorVal('#ERR!')

  if (node.name === 'IF') {
    const cond = evalScalar(ctx, node.args[0])
    if (cond.type === 'error') return cond
    let truthy
    if (cond.type === 'bool') {
      truthy = cond.value
    } else {
      const n = toNumber(cond)
      if (n.type === 'error') return n
      truthy = n.value !== 0
    }
    return evalScalar(ctx, truthy ? node.args[1] : node.args[2])
  }

  const rawValues = []
  for (const arg of node.args) rawValues.push(...evalArgumentValues(ctx, arg))
  for (const v of rawValues) if (v.type === 'error') return v

  if (node.name === 'COUNT') {
    return numberVal(rawValues.filter((v) => v.type === 'number').length)
  }

  const nums = []
  for (const v of rawValues) {
    const n = toNumber(v)
    if (n.type === 'error') return n
    nums.push(n.value)
  }
  switch (node.name) {
    case 'SUM':
      return finiteOrDivZero(nums.reduce((a, b) => a + b, 0))
    case 'MIN':
      return finiteOrDivZero(Math.min(...nums))
    case 'MAX':
      return finiteOrDivZero(Math.max(...nums))
    case 'AVG':
      return finiteOrDivZero(nums.reduce((a, b) => a + b, 0) / nums.length)
    case 'ABS':
      return finiteOrDivZero(Math.abs(nums[0]))
    default:
      throw new Error(`unreachable function ${node.name}`)
  }
}

function formatValue(v) {
  switch (v.type) {
    case 'number':
      return formatNumber(v.value)
    case 'text':
      return v.value
    case 'bool':
      return v.value ? 'TRUE' : 'FALSE'
    case 'error':
      return v.value
  }
}

function sortedKeys(sheet) {
  return [...sheet.keys()].sort((a, b) => {
    const ca = sheet.get(a)
    const cb = sheet.get(b)
    if (ca.col !== cb.col) return ca.col - cb.col
    return ca.row - cb.row
  })
}

/** Evaluate every declared cell and render `<address>=<value>` lines. */
export function evaluateAll(sheet) {
  const ctx = { sheet, cache: new Map() }
  let out = ''
  for (const key of sortedKeys(sheet)) {
    out += `${key}=${formatValue(getCellValue(ctx, key))}\n`
  }
  return out
}

export { sortedKeys }
"}

