const mode = process.argv[2]
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

let input = ''
process.stdin.setEncoding('utf8')
for await (const chunk of process.stdin) input += chunk

try {
  const sheet = parseSheet(input)
  const output = mode === 'values' ? evaluateAll(sheet) : computeDeps(sheet)
  process.stdout.write(output)
} catch (e) {
  if (e instanceof SheetError) {
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  throw e
}

